import React, { useRef, useCallback } from "react";
import clsx from "clsx";
import { SlideIndicator as SlideIndicatorStyles } from "@airbus/styles";
import { createUseStyles } from "../../lib/styling";
import { CommonProps } from "../helperTypes";
import useDeprecatedComponent from "../../lib/hooks/useDeprecatedComponent";

type Props = {
  /** callback function that is called with index of clicked step */
  onStepClick?: (
    evt: React.MouseEvent | React.KeyboardEvent,
    index: number
  ) => void;
  /**
   * pass 'vertical' to show progress indicators vertically
   * @default "horizontal"
   */
  orientation?: "horizontal" | "vertical" | undefined;
  /** index of current selected step */
  selected?: number;
  /** The total number of steps */
  total: number;
};

export type SlideIndicatorProps = Props & CommonProps;

const useStyles = createUseStyles(SlideIndicatorStyles, "slideindicator");
const STEP_SIZE = 24; //16px button width + 8px gap between the buttons

const SlideIndicator = ({
  className,
  total,
  selected = 0,
  orientation = "horizontal",
  onStepClick,
  style,
  ...rest
}: SlideIndicatorProps) => {
  const classes = useStyles();
  const maxStepsOnScreen = 7;
  const halfSteps = Math.floor(maxStepsOnScreen / 2);
  const hasOverflow = total > maxStepsOnScreen;

  // Compute offset translation
  let offset = 0;
  if (hasOverflow) {
    const maxOffset = total - maxStepsOnScreen;
    const idealOffset = selected - halfSteps;
    // Math.min ensures offset never goes past the last visible group of steps (maxOffset)
    // Math.max ensures offset never goes below 0
    offset = Math.max(0, Math.min(idealOffset, maxOffset));
  }

  // Define overflow states based on the calculated offset
  const overflowLeft = hasOverflow && offset > 0;
  const overflowRight = hasOverflow && offset < total - maxStepsOnScreen;

  const offsetStyle = {
    transform:
      orientation === "horizontal"
        ? `translate(${-offset * STEP_SIZE}px, 0)`
        : `translate(0, ${-offset * STEP_SIZE}px)`,
  };

  const buttonRefs = useRef<(HTMLButtonElement | null)[]>([]);
  const containerRef = useRef<HTMLDivElement>(null);

  const handleContainerFocus = useCallback(
    (e: React.FocusEvent<HTMLDivElement>) => {
      // Only handle focus if entering from outside the component
      if (
        e.target === containerRef.current &&
        (!e.relatedTarget ||
          !containerRef.current?.contains(e.relatedTarget as Node))
      ) {
        const defaultButton =
          buttonRefs.current[selected] || buttonRefs.current[0];
        defaultButton?.focus({ preventScroll: true });
      }
    },
    [selected]
  );

  // Unified handler for both Container and Button key events
  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent<HTMLDivElement>) => {
      const isHorizontal = orientation === "horizontal";
      const isNext = e.key === (isHorizontal ? "ArrowRight" : "ArrowDown");
      const isPrev = e.key === (isHorizontal ? "ArrowLeft" : "ArrowUp");

      if (!isNext && !isPrev) return;

      // Prevent default to stop browser scrolling
      e.preventDefault();
      e.stopPropagation();

      // Determine starting index:
      // If event came from a button, use its index. Otherwise (container focus), use selected.
      const targetIndex = buttonRefs.current.indexOf(
        e.target as HTMLButtonElement
      );
      const currentIndex = targetIndex >= 0 ? targetIndex : selected;
      const nextIndex = currentIndex + (isNext ? 1 : -1);

      if (nextIndex >= 0 && nextIndex < total) {
        buttonRefs.current[nextIndex]?.focus({ preventScroll: true });
        onStepClick?.(e, nextIndex);
      }
    },
    [orientation, selected, total, onStepClick]
  );

  const handleButtonClick = useCallback(
    (evt: React.MouseEvent<HTMLButtonElement, MouseEvent>, index: number) => {
      evt.currentTarget.focus({ preventScroll: true });
      onStepClick?.(evt, index);
    },
    [onStepClick]
  );

  return (
    <div className={classes.container} style={style}>
      <div
        ref={containerRef}
        tabIndex={0}
        onFocus={handleContainerFocus}
        onKeyDown={handleKeyDown}
        className={clsx(
          classes.root,
          className,
          orientation === "vertical" && classes._vertical
        )}
        role="tablist"
        aria-label="slide indicator"
        style={offsetStyle}
        {...rest}
      >
        {Array(total)
          .fill(undefined)
          .map((_, index) => (
            <button
              role="tab"
              aria-label={`step ${index}`}
              key={`slide-indicator-step-${index}`}
              onClick={(evt) => handleButtonClick(evt, index)}
              ref={(el) => (buttonRefs.current[index] = el)}
              tabIndex={index === selected ? 0 : -1}
              aria-selected={index === selected}
              className={clsx(
                classes.step,
                index === selected && classes.step_selected,
                overflowLeft && index <= offset && classes.step_end,
                overflowLeft && index === offset + 1 && classes.step_beforeend,
                overflowRight &&
                  index === offset + maxStepsOnScreen - 2 &&
                  classes.step_beforeend,
                overflowRight &&
                  index >= offset + maxStepsOnScreen - 1 &&
                  classes.step_end
              )}
            />
          ))}
      </div>
    </div>
  );
};

export default SlideIndicator;

// retro compatibility (v1/v2)
export type ProgressIndicatorProps = SlideIndicatorProps;
export const ProgressIndicator = (props: SlideIndicatorProps) => {
  useDeprecatedComponent("ProgressIndicator", "Please use SlideIndicator.");
  return <SlideIndicator {...props} />;
};
